<section class="card exit-records">
    <div class="section-heading"><div><h2>Exit workflow</h2><p>Record resignation, termination, notice and clearance history.</p></div><button type="button" class="btn" data-add="exits">Add exit record</button></div>
    <div class="repeater" data-repeater="exits">@foreach($exits as $i=>$row)<div class="repeater-row"><input type="hidden" name="exits[{{ $i }}][id]" value="{{ data_get($row,'id') }}"><input type="hidden" class="delete-flag" name="exits[{{ $i }}][_delete]" value="0"><div class="form-grid"><label>Leaving reason<select name="exits[{{ $i }}][leaving_reason_id]"><option value="">Select</option>@foreach($leavingReasons as $item)<option value="{{ $item->id }}" @selected(data_get($row,'leaving_reason_id') == $item->id)>{{ $item->name }}</option>@endforeach</select></label><label>Resignation date<input type="date" name="exits[{{ $i }}][resignation_date]" value="{{ data_get($row,'resignation_date') }}"></label><label>Last working date<input type="date" name="exits[{{ $i }}][last_working_date]" value="{{ data_get($row,'last_working_date') }}"></label><label>Notice end date<input type="date" name="exits[{{ $i }}][notice_end_date]" value="{{ data_get($row,'notice_end_date') }}"></label><label>Clearance status<select name="exits[{{ $i }}][clearance_status]">@foreach(['pending','in_progress','cleared'] as $status)<option value="{{ $status }}" @selected(data_get($row,'clearance_status','pending') === $status)>{{ str($status)->replace('_',' ')->title() }}</option>@endforeach</select></label><label>Exit status<select name="exits[{{ $i }}][status]">@foreach(['initiated','approved','completed','cancelled'] as $status)<option value="{{ $status }}" @selected(data_get($row,'status','initiated') === $status)>{{ str($status)->title() }}</option>@endforeach</select></label><label class="wide">Remarks<textarea name="exits[{{ $i }}][remarks]">{{ data_get($row,'remarks') }}</textarea></label></div><button type="button" class="remove-row">Remove</button></div>@endforeach</div>
    <template data-template="exits"><div class="repeater-row"><input type="hidden" class="delete-flag" name="exits[__INDEX__][_delete]" value="0"><div class="form-grid"><label>Leaving reason<select name="exits[__INDEX__][leaving_reason_id]"><option value="">Select</option>@foreach($leavingReasons as $item)<option value="{{ $item->id }}">{{ $item->name }}</option>@endforeach</select></label><label>Resignation date<input type="date" name="exits[__INDEX__][resignation_date]"></label><label>Last working date<input type="date" name="exits[__INDEX__][last_working_date]"></label><label>Notice end date<input type="date" name="exits[__INDEX__][notice_end_date]"></label><label>Clearance status<select name="exits[__INDEX__][clearance_status]"><option value="pending">Pending</option><option value="in_progress">In progress</option><option value="cleared">Cleared</option></select></label><label>Exit status<select name="exits[__INDEX__][status]"><option value="initiated">Initiated</option><option value="approved">Approved</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></label><label class="wide">Remarks<textarea name="exits[__INDEX__][remarks]"></textarea></label></div><button type="button" class="remove-row">Remove</button></div></template>
